import{_ as i,o as a,c as t,a4 as e}from"./chunks/framework.vNSRaLQv.js";const k=JSON.parse('{"title":"GO 为什么\\"不能有下划线\\"——以及它跟内核的关系","description":"","frontmatter":{"title":"GO 为什么\\"不能有下划线\\"——以及它跟内核的关系","date":"2026-08-30T00:00:00.000Z"},"headers":[],"relativePath":"posts/GO为什么不能有下划线-与内核的关系.md","filePath":"posts/GO为什么不能有下划线-与内核的关系.md"}'),o={name:"posts/GO为什么不能有下划线-与内核的关系.md"};function n(l,s,d,h,r,p){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="go-为什么-不能有下划线-——以及它跟内核的关系" tabindex="-1">GO 为什么&quot;不能有下划线&quot;——以及它跟内核的关系 <a class="header-anchor" href="#go-为什么-不能有下划线-——以及它跟内核的关系" aria-label="Permalink to &quot;GO 为什么&quot;不能有下划线&quot;——以及它跟内核的关系&quot;">​</a></h1><blockquote><p>背景：把 OpenList v4.2.5 交叉编译部署到盒子（Hi3798MV100）时，盒子内核版本号 <code>4.4.35_ecoo_81082668</code> 里带了下划线，导致 Go 生态里解析内核版本的相关逻辑出问题， 甚至影响编译/运行需要更换 Go 版本。本文讲清楚两件事：Go 里&quot;下划线&quot;到底哪些地方不行； 以及内核版本号里的下划线是怎么跟 Go 扯上关系的。</p></blockquote><hr><h2 id="一、go-语言里-下划线-的真实规则-先纠正流传的说法" tabindex="-1">一、Go 语言里&quot;下划线&quot;的真实规则（先纠正流传的说法） <a class="header-anchor" href="#一、go-语言里-下划线-的真实规则-先纠正流传的说法" aria-label="Permalink to &quot;一、Go 语言里&quot;下划线&quot;的真实规则（先纠正流传的说法）&quot;">​</a></h2><p>&quot;Go 不能有下划线&quot;是个笼统说法，要分场合：</p><h3 id="_1-真正-不行-的地方-源文件名不能以-开头" tabindex="-1">1. 真正&quot;不行&quot;的地方：源文件名不能以 <code>_</code> 开头 <a class="header-anchor" href="#_1-真正-不行-的地方-源文件名不能以-开头" aria-label="Permalink to &quot;1. 真正&quot;不行&quot;的地方：源文件名不能以 \`_\` 开头&quot;">​</a></h3><p>Go 工具链有一条硬规则：<strong>以 <code>.</code> 或 <code>_</code> 开头的源文件会被直接忽略</strong>，根本不参与编译。</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">// 下面的文件会被 go build 静默忽略，不报错也不编译</span></span>
<span class="line"><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">_foo</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">.</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">go</span></span>
<span class="line"><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">bar</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">.</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">go</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">   // 正常</span></span></code></pre></div><p>这是新手最容易踩的坑——<code>_foo.go</code> 里写的函数、main 入口全都&quot;神秘消失&quot;。</p><h3 id="_2-恰恰相反-下划线在文件名里是-平台特化-的关键字" tabindex="-1">2. 恰恰相反，下划线在文件名里是&quot;平台特化&quot;的关键字 <a class="header-anchor" href="#_2-恰恰相反-下划线在文件名里是-平台特化-的关键字" aria-label="Permalink to &quot;2. 恰恰相反，下划线在文件名里是&quot;平台特化&quot;的关键字&quot;">​</a></h3><p>Go 用文件名的后缀做<strong>构建约束（build constraint）</strong>，下划线在这里是<strong>必须用</strong>的约定：</p><table tabindex="0"><thead><tr><th>文件名后缀</th><th>含义</th></tr></thead><tbody><tr><td><code>xxx_linux.go</code></td><td>只在 Linux 编译</td></tr><tr><td><code>xxx_arm64.go</code></td><td>只在 arm64 编译</td></tr><tr><td><code>xxx_linux_arm64.go</code></td><td>只在 Linux + arm64 编译</td></tr></tbody></table><p>所以交叉编译时经常见到 <code>xxx_linux_arm64.go</code>——这里的下划线不但允许，还是 Go 平台适配的核心机制。</p><h3 id="_3-变量-函数-包名里-可以-有下划线" tabindex="-1">3. 变量/函数/包名里&quot;可以&quot;有下划线 <a class="header-anchor" href="#_3-变量-函数-包名里-可以-有下划线" aria-label="Permalink to &quot;3. 变量/函数/包名里&quot;可以&quot;有下划线&quot;">​</a></h3><ul><li>标识符：<code>my_var</code> 合法（只是不能以数字开头）。</li><li>包名：规范上<strong>不推荐</strong>带下划线（gofmt 风格），但编译器允许。</li><li>模块/导入路径：允许下划线。</li><li>单独的 <code>_</code>：是<strong>空标识符（blank identifier）</strong>，用来忽略返回值，不能引用。</li></ul><blockquote><p>一句话总结：Go 真正禁止的是&quot;<strong>文件名以 <code>_</code> 开头</strong>&quot;；其余地方下划线大多可以用， 甚至文件名 <code>_linux_arm64.go</code> 这种下划线是功能性的。</p></blockquote><hr><h2 id="二、内核版本号里的下划线——真正的矛盾点" tabindex="-1">二、内核版本号里的下划线——真正的矛盾点 <a class="header-anchor" href="#二、内核版本号里的下划线——真正的矛盾点" aria-label="Permalink to &quot;二、内核版本号里的下划线——真正的矛盾点&quot;">​</a></h2><h3 id="_1-标准内核版本号长什么样" tabindex="-1">1. 标准内核版本号长什么样 <a class="header-anchor" href="#_1-标准内核版本号长什么样" aria-label="Permalink to &quot;1. 标准内核版本号长什么样&quot;">​</a></h3><p>Linux 内核版本号标准格式是 <code>主.次.补丁[-额外]</code>，额外部分用<strong>连字符</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>4.4.35                 # 主.次.补丁</span></span>
<span class="line"><span>5.10.0-23-generic      # 带 distro 后缀，用连字符</span></span>
<span class="line"><span>6.6.0-rc5              # 预发布</span></span></code></pre></div><h3 id="_2-盒子这个内核-违规-了" tabindex="-1">2. 盒子这个内核&quot;违规&quot;了 <a class="header-anchor" href="#_2-盒子这个内核-违规-了" aria-label="Permalink to &quot;2. 盒子这个内核&quot;违规&quot;了&quot;">​</a></h3><p>盒子内核 <code>uname -r</code> 返回：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>4.4.35_ecoo_81082668</span></span></code></pre></div><p><code>_ecoo_81082668</code> 是厂商（ECOO）自定义的后缀，<strong>没有用标准连字符，而是塞了下划线</strong>。 这种&quot;带下划线&quot;的版本号在内核/设备厂商定制里很常见，但对上层程序不友好。</p><h3 id="_3-为什么这会跟-go-扯上关系" tabindex="-1">3. 为什么这会跟 Go 扯上关系 <a class="header-anchor" href="#_3-为什么这会跟-go-扯上关系" aria-label="Permalink to &quot;3. 为什么这会跟 Go 扯上关系&quot;">​</a></h3><p>Go 生态里有一堆库要<strong>读取并解析内核版本</strong>，最典型的是 <code>gopsutil</code>（<code>host</code> 模块）以及 各类特性检测代码。它们普遍用类似下面的正则去抠版本号：</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">// gopsutil/host 里的内核版本解析，约等于</span></span>
<span class="line"><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">re</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> :=</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> regexp</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">.</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">MustCompile</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">\`</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">\\d+\\.\\d+(\\.\\d+)?</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">\`</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span></span>
<span class="line"><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">ver</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> :=</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;"> re</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">.</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">FindString</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">(</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">kernelVersion</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"> // 从 uname 输出里抓版本</span></span></code></pre></div><p>对标准版本号没问题，但遇到 <code>4.4.35_ecoo_81082668</code>：</p><ul><li><strong>宽松解析</strong>（正则抓前缀）：能抓到 <code>4.4.35</code>，只是特性判断仍按老内核走——可能&quot;以为&quot;内核很老，某些新特性不开。</li><li><strong>严格解析</strong>（按 <code>.</code> 切分后强转整数 / 用版本比较库）：遇到 <code>_ecoo_81082668</code> 段时， 解析失败或 panic，或抛出&quot;非法版本号&quot;错误。</li></ul><h3 id="_4-对-openlist-的具体影响" tabindex="-1">4. 对 OpenList 的具体影响 <a class="header-anchor" href="#_4-对-openlist-的具体影响" aria-label="Permalink to &quot;4. 对 OpenList 的具体影响&quot;">​</a></h3><p>OpenList / 依赖库在编译期或运行期可能做类似判断：</p><ul><li>用内核版本决定是否启用某些 syscall / 特性（<code>statx</code>、<code>io_uring</code>、<code>faccessat2</code> 等）。</li><li>版本号带下划线导致解析失败 → 特性检测异常 → 行为不对、甚至需要换 Go 工具链版本重新编译才跑得起来。</li><li>这就是为什么升级到 v4.2.5 时，卡在内核版本号 <code>4.4.35_ecoo_81082668</code> 上， 需要 Go 1.25 配合交叉编译才能出活。</li></ul><hr><h2 id="三、结论-一句话版本" tabindex="-1">三、结论（一句话版本） <a class="header-anchor" href="#三、结论-一句话版本" aria-label="Permalink to &quot;三、结论（一句话版本）&quot;">​</a></h2><ul><li>Go 语言本身：只有&quot;<strong>源文件名不能以 <code>_</code> 开头</strong>&quot;这一条硬限制；下划线在文件名平台后缀 （<code>_linux_arm64.go</code>）里反而是功能性的。</li><li>你遇到的真问题不是&quot;Go 语法不让用下划线&quot;，而是<strong>厂商内核版本号 <code>4.4.35_ecoo_81082668</code> 里违规夹了下划线</strong>，导致 Go 生态里解析内核版本号的库（如 gopsutil）解析失败/误判， 从而影响交叉编译与运行行为。</li></ul><blockquote><p>换个角度想：<strong>下划线在&quot;Go 源码&quot;里是被精心设计的工具，在&quot;内核版本号&quot;里却是被人为 破坏格式的雷</strong>。把内核后缀改成标准连字符（如 <code>4.4.35-ecoo</code>）或让上层解析库更宽容， 问题就绕过去了。</p></blockquote><hr><p><em>生成时间：2026-08-30 · 主题来自 Hi3798MV100 盒子（内核 4.4.35_ecoo_81082668）上部署 OpenList v4.2.5 的排障过程</em></p>`,39)])])}const g=i(o,[["render",n]]);export{k as __pageData,g as default};
